Substitute $x$ with $\ddot{x}$  in Eq.~\ref{phdbackwardsmoothing}, we get 
\begin{equation}
{D_{t|k}}({\ddot x_t}) = {D_{t|t}}({\ddot x_t})\left[ {{P_s}({{\ddot x}_t})\int {\frac{{{D_{t + 1|k}}({{\ddot x}_{t + 1}}){f_{t + 1|t}}({{\ddot x}_{t + 1}}|{{\ddot x}_t})}}{{{D_{t + 1|t}}({{\ddot x}_{t + 1}})}}d{{\ddot x}_{t + 1}} + 1 - {P_s}({{\ddot x}_t})} } \right]
\end{equation}

where 
\begin{equation}
{D_{t + 1|t}}({\ddot x_{t + 1}}) = \gamma ({\ddot x_{t + 1}}) + \int {\left[ {{P_s}({{\ddot x}_t}){f_{t + 1|t}}({{\ddot x}_{t + 1}}|{{\ddot x}_t}) + {\beta _{t + 1|t}}({{\ddot x}_{t + 1}}|{{\ddot x}_t})} \right]} {D_{t|t}}({\ddot x_t})d{\ddot x_t}
\end{equation}
Then, substitute  $\ddot x = (x,o)$  to the above equation.

Note that if we use $r$ to replace $o$, we will get the multi-model PHD filter and multi-model PHD smoothing, which is consistant with the work in~\cite{nadarajah-a}.

The class-conditioned backward PHD filter is,
\begin{eqnarray}
{D_{t|k}}({x_t},c|{Z_{1:k}}) = {D_{t|t}}({x_t},c|{Z_{1:t}})\left[ {{P_s}({x_t},c)\sum\limits_{c'} {\int {\frac{{{D_{t + 1|k}}({x_{t + 1}},c'|{Z_{1:k}}){f_{t + 1|t}}({x_{t + 1}},c'|{x_t},c)}}{{{D_{t + 1|t}}({x_{t + 1}},c'|{Z_{1:t}})}}d{x_{t + 1}} + 1 - {P_s}({x_t},c)} } } \right],
\end{eqnarray}

where
\begin{equation}\begin{array}{l}
{D_{t + 1|t}}({x_{t + 1}},c' = c|{Z_{1:t}}) = \gamma ({x_{t + 1}},c') + \int {{P_s}({x_t},c){f_{t + 1|t}}({x_{t + 1}}|{x_t},c){D_{t|t}}({x_t},c|{Z_{1:t}})d{x_t}} \\
 {\kern 1pt} {\kern 1pt}  + \sum\limits_{c''} {\int {{\beta _{t + 1|t}}({x_{t + 1}},c' = c|{x_t},c''){D_{t|t}}({x_t},c''|{Z_{1:t}})d{x_t}} } .
\end{array}
\end{equation}

we extend $x$ by adding the class information $c$,  i.e. $\ddot{x} =(x, c)$ and substuting to Equation~\ref{phdbackwardsmoothing}. We get  
\begin{equation}
{D_{t|k}}({x_t},c|{Z_{1:k}}) = {D_{t|t}}({x_t},c|{Z_{1:t}})
  \times \left[ {{P_s}({x_t},c)\sum\limits_{c'} {\int {\frac{{{D_{t + 1|k}}({x_{t + 1}},c'|{Z_{1:k}}){f_{t + 1|t}}({x_{t + 1}},c'|{x_t},c)}}{{{D_{t + 1|t}}({x_{t + 1}},c'|{Z_{1:t}})}}d{x_{t + 1}} + 1 - {P_s}({x_t},c)} } } \right]
\end{equation}

where 
\begin{equation}
\begin{array}{l}
{D_{t + 1|t}}({x_{t + 1}},c'|{Z_{1:t}}) = \gamma ({x_{t + 1}},c')
 + \sum\limits_c {\int {\left[ {{P_s}({x_t},c){f_{t + 1|t}}({x_{t + 1}},c'|{x_t},c) + {\beta _{t + 1|t}}({x_{t + 1}},c'|{x_t},c)} \right]} {D_{t|t}}({x_t},c)d{x_t}} 
\end{array}
\end{equation}
 Assume that the type of existing target does not change with time.  Using Equation ~\ref{equ:targetclass} we can get the PHD-JDTC smoothing.

 The final state estimation with smoothing will be
\begin{equation}
{D_{t|k}}({x_t}|{Z_{1:k}}) = \sum\limits_c {{D_{t|k}}({x_t},c|{Z_{1:k}})}
 \end{equation}

The number of target after smooth is 
\begin{equation}
{N_{t|k}}({x_t}) = \int {{D_{t|k}}({x_t}|{Z_{1:k}})d{x_t}} 
\end{equation}
